                      </Button>
                    )
                    : (
                      <Button
                        onClick={() => setSelection(selection.select(data[3]))}
                      >
                        Select {data[3].country}
                      </Button>
                    )}
                </span>

                <span id="button-select-finland">
                  {' '}
                  {selection.isSelected(data[5])
                    ? (
                      <Button
