                      </Button>
                    )
                    : (
                      <Button
                        onClick={() => setSelection(selection.select(data[5]))}
                      >
                        Select {data[5].country}
                      </Button>
                    )}
                </span>
              </>
            )}
          </Col>
        </Row>
      </Grid>
    </div>
  );
